/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int K) {
        if (root == null || target == null) {
            return null;
        }

        var graph = new HashMap<TreeNode, TreeNode>();
        buildGraph(graph, root, null);

        return bfs(graph, target, K);
    }

    void buildGraph(HashMap<TreeNode, TreeNode> graph, TreeNode root, TreeNode parent) {
        if (root == null) {
            return;
        }

        buildGraph(graph, root.left, root);
        buildGraph(graph, root.right, root);
        graph.put(root, parent);
    }

    List<Integer> bfs(HashMap<TreeNode, TreeNode> graph, TreeNode target, int K) {
        var result = new ArrayList<Integer>();
        var visit = new HashSet<TreeNode>();

        var queue = new LinkedList<TreeNode>();
        var step = 0;
        queue.offer(target);
        visit.add(target);

        while (!queue.isEmpty() && step <= K) {
            var size = queue.size();
            for (var i = 0; i < size; i++) {
                var cur = queue.pop();
                if (cur.left != null && !visit.contains(cur.left)) {
                    queue.offer(cur.left);
                    visit.add(cur.left);
                }
                if (cur.right != null && !visit.contains(cur.right)) {
                    queue.offer(cur.right);
                    visit.add(cur.right);
                }
                var parent = graph.get(cur);
                if (parent != null && !visit.contains(parent)) {
                    queue.offer(parent);
                    visit.add(parent);
                }

                if (step == K) {
                    result.add(cur.val);
                }
            }

            step++;
        }

        return result;
    }
}

class Solution {
    Map<Integer, List<Integer>> graph;
    List<Integer> answer;
    Set<Integer> visited;

    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        graph = new HashMap<>();
        buildGraph(root, null);

        answer = new ArrayList<>();
        visited = new HashSet<>();
        visited.add(target.val);

        dfs(target.val, 0, k);

        return answer;
    }

    // Recursively build the undirected graph from the given binary tree.
    private void buildGraph(TreeNode cur, TreeNode parent) {
        if (cur != null && parent != null) {
            graph.computeIfAbsent(cur.val, k -> new ArrayList<>()).add(parent.val);
            graph.computeIfAbsent(parent.val, k -> new ArrayList<>()).add(cur.val);
        }
        if (cur.left != null) {
            buildGraph(cur.left, cur);
        }
        if (cur.right != null) {
            buildGraph(cur.right, cur);
        }
    }

    private void dfs(int cur, int distance, int k) {
        if (distance == k) {
            answer.add(cur);
            return;
        }
        for (int neighbor : graph.getOrDefault(cur, new ArrayList<>())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                dfs(neighbor, distance + 1, k);
            }
        }
    }
}

class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        dfsBuild(root, null, graph);

        List<Integer> answer = new ArrayList<>();
        Set<Integer> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();

        // Add the target node to the queue with a distance of 0
        queue.add(new int[]{target.val, 0});
        visited.add(target.val);

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int node = cur[0], distance = cur[1];

            // If the current node is at distance k from target,
            // add it to the answer list and continue to the next node.
            if (distance == k) {
                answer.add(node);
                continue;
            }

            // Add all unvisited neighbors of the current node to the queue.
            for (int neighbor : graph.getOrDefault(node, new ArrayList<>())) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.add(new int[]{neighbor, distance + 1});
                }
            }
        }

        return answer;
    }

    // Recursively build the undirected graph from the given binary tree.
    private void dfsBuild(TreeNode cur, TreeNode parent, Map<Integer, List<Integer>> graph) {
        if (cur != null && parent != null) {
            int curVal = cur.val, parentVal = parent.val;
            graph.putIfAbsent(curVal, new ArrayList<>());
            graph.putIfAbsent(parentVal, new ArrayList<>());
            graph.get(curVal).add(parentVal);
            graph.get(parentVal).add(curVal);
        }

        if (cur != null && cur.left != null) {
            dfsBuild(cur.left, cur, graph);
        }

        if (cur != null && cur.right != null) {
            dfsBuild(cur.right, cur, graph);
        }
    }
}

class Solution:
    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:
        # Recursively add a parent pointer to each node.
        def add_parent(cur, parent):
            if cur:
                cur.parent = parent
                add_parent(cur.left, cur)
                add_parent(cur.right, cur) 
        add_parent(root, None)

        answer = []
        visited = set()
        def dfs(cur, distance):
            if not cur or cur in visited:
                return
            visited.add(cur)
            if distance == 0:
                answer.append(cur.val)
                return
            dfs(cur.parent, distance - 1)
            dfs(cur.left, distance - 1)
            dfs(cur.right, distance - 1)

        dfs(target, k)

        return answer

